def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses into separate strings.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, where each string represents a separate group of parentheses.
    """
    result = []
    stack = []
    current_group = ''
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                raise ValueError("Unbalanced parentheses")
            stack.pop()
        else:
            current_group += char
        if len(stack) == 0 and current_group != '':
            result.append(current_group)
            current_group = ''
    if len(stack) != 0:
        raise ValueError("Unbalanced parentheses")
    return result

def below_zero(operations: List[int]) -> bool:
    """
    Given a list of deposit and withdrawal operations, return True if the balance of the account falls below zero at any point, and False otherwise.
    """
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def max_value_on_paths(N, grid_values):
    # Initialize the dynamic programming table
    dp = [[0] * (N+1) for _ in range(N+1)]

    # Populate the dynamic programming table
    for i in range(1, N+1):
        for j in range(1, N+1):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

    # Calculate the maximum sum of values collected on two paths
    max_sum = 0
    for i in range(1, N+1):
        for j in range(1, N+1):
            max_sum = max(max_sum, dp[i][j] + dp[N-i+1][N-j+1])

    return max_sum

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.

    Example:
        >>> find_number_combinations()
        [(123, 246, 369), (124, 248, 372), ...]
    """
    combinations = []
    for i in range(1, 9):
        for j in range(1, 9):
            if j == i * 2:
                for k in range(1, 9):
                    if k == i * 3:
                        combinations.append((i, j, k))
    return sorted(combinations)

