def verify_isbn(isbn):
    if not isbn:
        raise ValueError("Invalid ISBN")

    isbn = isbn.replace("-", "")
    isbn_digits = isbn[:-1]
    isbn_checksum = isbn[-1]

    if isbn_checksum.isdigit():
        isbn_checksum = int(isbn_checksum)
    else:
        isbn_checksum = 10

    calculated_checksum = 0
    for i, digit in enumerate(isbn_digits):
        if digit.isdigit():
            calculated_checksum += (10 - i) * int(digit)
        else:
            raise ValueError("Invalid ISBN")

    if calculated_checksum % 11 == 0:
        return "Right"
    else:
        isbn_corrected = isbn[:-1] + str(11 - calculated_checksum % 11)
        return isbn_corrected

def count_sequences(n, last, memo):
    if last in memo:
        return memo[last]
    total = 1 if last <= n * 2 else 0
    for i in range(n + 1, last):
        if i <= n * 2:
            total += count_sequences(n, i, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 % (x0 * a) == 0:
            b = y0 // (x0 * a)
            if math.gcd(a, b) == 1:
                count += 2 if a != b else 1
    return count

def check_scenario(scenario, liar_count, statements, days_of_week):
    # Check if the scenario is consistent with the statements
    for statement in statements[scenario]:
        if statement not in days_of_week and not liar_count.issuperset(statements[scenario]):
